/// <summary>
/// Extension of TAMRebateDeal form
/// </summary>
[ExtensionOf(formStr(TAMRebateDeal))]
internal final class METTAMRebateDealFrm_Extension
{
}

Method.Source:
/// <summary>
/// Init method from Form
/// </summary>
public void init()
{
    next init();
    // CB705_VendorRebatePosting
    FormDataSource tamRebateDeal_ds = this.dataSource(FormDatasourceStr(TAMRebateDeal, TAMRebateDeal));
    FormDataSource tamRebateTable_ds = this.dataSource(FormDatasourceStr(TAMRebateDeal, TAMRebateTable));

    // CB705_VendorRebatePosting
    /*FormControl vendAccount = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDeal_METVendAccount)) as FormControl;        
    FormControl extRef = this.design().controlName(formControlStr(TAMRebateDeal, METExternalRebateDealReference)) as FormControl;
    FormControl priceComponentCode = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METPriceComponentCode)) as FormControl;
    FormControl priceAttributeGroupCombination = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METPriceAttributeGroupCombination)) as FormControl;
    FormControl headerPriceAttributeGroup = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METHeaderPriceAttributeGroup)) as FormControl;*/
    FormDataObject vendAccount = tamRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVendAccount));
    FormDataObject extRef = tamRebateDeal_ds.object(fieldNum(TAMRebateDeal, METExternalRebateDealReference));
    FormDataObject priceComponentCode = tamRebateTable_ds.object(fieldNum(TAMRebateTable, METPriceComponentCode));
    FormDataObject priceAttributeGroupCombination = tamRebateTable_ds.object(fieldNum(TAMRebateTable, METPriceAttributeGroupCombination));
    FormDataObject headerPriceAttributeGroup = tamRebateTable_ds.object(fieldNum(TAMRebateTable, METHeaderPriceAttributeGroup));

    FormControl headerPriceAttributeGroupDetail = this.design().controlName(formControlStr(TAMRebateDeal, METHeaderPriceAttributeGroupDetail)) as FormControl;
    FormControl linePriceAttributeGroup = this.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METLinePriceAttributeGroup)) as FormControl;
    FormControl linePriceAttributeGroupDetail = this.design().controlName(formControlStr(TAMRebateDeal, METLinePriceAttributeGroupDetail)) as FormControl;

    // Bug 293936: CB705 - Vendor rebate deals shows additional fields when opened from all vendor rebate management deals
    //if (this.args().menuItemName() == menuitemdisplaystr(TAMRebateDealListPageVendRebate))
    if (TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend)
    {
        vendAccount.visible(true);
        extRef.visible(true);
        priceComponentCode.visible(false);
        priceAttributeGroupCombination.visible(false);
        headerPriceAttributeGroup.visible(false);
        headerPriceAttributeGroupDetail.visible(true);
        linePriceAttributeGroup.visible(false);
        linePriceAttributeGroupDetail.visible(true);
    }
    else
    {
        vendAccount.visible(true);
        extRef.visible(false);
        priceComponentCode.visible(false);
        priceAttributeGroupCombination.visible(false);
        headerPriceAttributeGroup.visible(false);
        headerPriceAttributeGroupDetail.visible(false);
        linePriceAttributeGroup.visible(false);
        linePriceAttributeGroupDetail.visible(false);
    }

}

/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// Cannot extend TAMRebateDeal\active as Hookable false and allowEdit reset after the super (cannot use eventHandler there)
/// </summary>
public void setRestrictionForDateRangeOfRebateDeal()
{
    next setRestrictionForDateRangeOfRebateDeal();

    FormDataSource inventDim_ds = this.dataSource(FormDatasourceStr(TAMRebateDeal, InventDim));
    inventDim_ds.allowEdit(!TAMRebateDeal.METUseExternalSellData);
}
